package com.example.ecommerce.config;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;import com.example.ecommerce.user.*;import com.example.ecommerce.product.*;import org.springframework.security.crypto.password.PasswordEncoder;import java.math.*;@Configuration public class DataInitializer{@Bean CommandLineRunner seed(UserRepository u,ProductRepository p,CategoryRepository c,PasswordEncoder e){return a->{if(!u.existsByEmail("admin@harmesh-k-mart.com")){User x=new User();x.setName("Harmesh K-mart Admin");x.setEmail("admin@harmesh-k-mart.com");x.setPassword(e.encode("Admin@123"));x.setRole(Role.ADMIN);u.save(x);}if(p.count()==0){Category cat=new Category();cat.setName("Electronics");c.save(cat);for(String n:new String[]{"Laptop","Wireless Headphones","Smart Watch","Mechanical Keyboard"}){Product z=new Product();z.setName(n);z.setDescription("Premium "+n+" from Harmesh K-mart");z.setPrice(new BigDecimal("1999"));z.setStock(50);z.setCategory(cat);z.setRating(4.5);p.save(z);}}};}}
